<main>
  <h1>Weekend Trip Split</h1>
  <p class="sub">Track who paid for what, then see exactly who owes whom. Everyone shares the total equally.</p>
  <p class="status" id="status" aria-live="polite"></p>

  <section class="card" aria-labelledby="people-h">
    <h2 id="people-h">People</h2>
    <div class="chips" id="peopleList"></div>
    <div class="add-row">
      <label class="sr-only" for="personName">Add a person</label>
      <input id="personName" type="text" placeholder="Add a name…" maxlength="24">
      <button class="btn btn-primary" id="addPerson" type="button">Add</button>
    </div>
    <div id="personConfirm" class="confirm" hidden></div>
  </section>

  <section class="card" aria-labelledby="exp-h">
    <h2 id="exp-h">Expenses</h2>
    <p class="err" id="expError" role="alert"></p>
    <form id="expForm">
      <div class="field">
        <label for="expTitle">What was it?</label>
        <input id="expTitle" type="text" placeholder="e.g. Dinner, fuel, tickets" maxlength="60">
      </div>
      <div class="field">
        <label for="expAmount">Amount (€)</label>
        <input id="expAmount" type="number" inputmode="decimal" step="0.01" min="0" placeholder="0.00">
      </div>
      <div class="field">
        <label for="expPayer">Paid by</label>
        <select id="expPayer"></select>
      </div>
      <div class="field">
        <label for="expSplit">Split between</label>
        <select id="expSplit"></select>
      </div>
      <button class="btn btn-primary" type="submit">Add expense</button>
    </form>
    <div id="expList"></div>
    <div id="expConfirm" class="confirm" hidden></div>
  </section>

  <section class="card" aria-labelledby="res-h">
    <h2 id="res-h">Who owes whom</h2>
    <div id="results"></div>
  </section>
</main>

<script>
(function(){
  const KEY = 'weekend-trip-split-v1';
  const hasStorage = !!(window.alfy && window.alfy.storage);
  const $ = id => document.getElementById(id);

  let state = { people:[], expenses:[], nextPerson:1, nextExpense:1 };

  function money(n){ return new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'}).format(n); }
  function esc(s){ return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
  function personById(id){ return state.people.find(p => p.id === id); }
  function status(msg){ $('status').textContent = msg; }

  async function load(){
    if(hasStorage){
      try{
        const s = await window.alfy.storage.get(KEY);
        if(s && Array.isArray(s.people) && Array.isArray(s.expenses)){
          state.people = s.people; state.expenses = s.expenses;
          state.nextPerson = s.nextPerson || 1; state.nextExpense = s.nextExpense || 1;
        }
      }catch(e){}
    }
    if(state.people.length === 0){
      ['Levente','Anna','Peti'].forEach(name => addPerson(name, true));
    }
  }
  function save(){ if(hasStorage){ window.alfy.storage.set(KEY, state).catch(()=>{}); } }

  function addPerson(name, silent){
    name = name.trim();
    if(!name) return false;
    if(state.people.some(p => p.name.toLowerCase() === name.toLowerCase())) return false;
    state.people.push({ id:'p'+(state.nextPerson++), name });
    if(!silent){ save(); render(); status(name + ' added.'); }
    return true;
  }

  function removePerson(id){
    const p = personById(id); if(!p) return;
    state.people = state.people.filter(x => x.id !== id);
    state.expenses = state.expenses.filter(e => e.payerId !== id && !e.splitIds.includes(id));
    save(); render(); status(p.name + ' removed.');
  }

  function removeExpense(id){
    const e = state.expenses.find(x => x.id === id); if(!e) return;
    state.expenses = state.expenses.filter(x => x.id !== id);
    save(); render(); status('Expense removed.');
  }

  function computeBalances(){
    const bal = {}; state.people.forEach(p => bal[p.id] = 0);
    const n = state.people.length;
    if(n === 0) return bal;
    state.expenses.forEach(e => {
      const ids = e.splitIds.filter(id => bal[id] !== undefined);
      if(ids.length === 0) return;
      const share = e.amount / ids.length;
      if(bal[e.payerId] !== undefined) bal[e.payerId] += e.amount;
      ids.forEach(id => bal[id] -= share);
    });
    return bal;
  }

  function computeSettlements(bal){
    const r = v => Math.round(v*100)/100;
    const creditors = state.people.map(p => ({id:p.id, name:p.name, amt:r(bal[p.id])})).filter(x => x.amt > 0.005).sort((a,b)=>b.amt-a.amt);
    const debtors = state.people.map(p => ({id:p.id, name:p.name, amt:r(-bal[p.id])})).filter(x => x.amt > 0.005).sort((a,b)=>b.amt-a.amt);
    const out = []; let ci=0, di=0;
    while(ci < creditors.length && di < debtors.length){
      const pay = Math.min(creditors[ci].amt, debtors[di].amt);
      if(pay > 0.005){
        out.push({ from:debtors[di].name, to:creditors[ci].name, amount:pay });
        creditors[ci].amt -= pay; debtors[di].amt -= pay;
      }
      if(creditors[ci].amt <= 0.005) ci++;
      if(debtors[di].amt <= 0.005) di++;
    }
    return out;
  }

  function renderPeople(){
    const list = $('peopleList');
    list.innerHTML = state.people.map(p =>
      '<button class="chip" type="button" data-del-person="'+esc(p.id)+'" aria-label="Remove '+esc(p.name)+'"><span class="dot" aria-hidden="true"></span>'+esc(p.name)+'<span class="x" aria-hidden="true">×</span></button>'
    ).join('');
  }

  function renderPayerOptions(){
    $('expPayer').innerHTML = state.people.map(p => '<option value="'+esc(p.id)+'">'+esc(p.name)+'</option>').join('');
    const sel = $('expSplit');
    sel.innerHTML = '<option value="all">Everyone ('+state.people.length+')</option>' +
      state.people.map(p => '<option value="'+esc(p.id)+'">Only '+esc(p.name)+'</option>').join('');
  }

  function renderExpenses(){
    const list = $('expList');
    if(state.expenses.length === 0){
      list.innerHTML = '<p class="empty">No expenses yet. Add who paid for what using the form above.</p>';
      return;
    }
    list.innerHTML = state.expenses.map(e => {
      const payer = personById(e.payerId);
      const split = e.splitIds.map(id => (personById(id)||{}).name).filter(Boolean);
      const splitLabel = (e.splitIds.length === state.people.length) ? 'Everyone' : split.join(', ');
      return '<div class="expense"><div class="exp-main"><div class="exp-title">'+esc(e.title)+'</div>'+
        '<div class="exp-meta">'+esc(payer?payer.name:'Unknown')+' paid · split '+esc(splitLabel)+'</div></div>'+
        '<div class="exp-amount">'+money(e.amount)+'</div>'+
        '<button class="del" type="button" data-del-expense="'+esc(e.id)+'" aria-label="Remove '+esc(e.title)+'">×</button></div>';
    }).join('');
  }

  function renderResults(){
    const el = $('results');
    const bal = computeBalances();
    if(state.people.length === 0){ el.innerHTML = '<p class="empty">Add some people to get started.</p>'; return; }
    if(state.expenses.length === 0){ el.innerHTML = '<p class="empty">Add expenses to see the balances.</p>'; return; }
    const total = state.expenses.reduce((s,e)=>s+e.amount,0);
    const share = total / state.people.length;
    let html = '<div class="row"><span>Total spent</span><span class="amt">'+money(total)+'</span></div>'+
      '<div class="row"><span>Each person\'s share</span><span class="amt">'+money(share)+'</span></div>';
    state.people.forEach(p => {
      const v = Math.round(bal[p.id]*100)/100;
      const cls = v >= 0 ? 'pos' : 'neg';
      const txt = v >= 0 ? 'gets back ' + money(v) : 'owes ' + money(-v);
      html += '<div class="row"><span>'+esc(p.name)+'</span><span class="amt '+cls+'">'+txt+'</span></div>';
    });
    const st = computeSettlements(bal);
    html += '<h3 style="margin:18px 0 4px;font-size:16px">Settle up</h3>';
    if(st.length === 0){ html += '<p class="empty">Everyone is already even. 🎉</p>'; }
    else {
      html += st.map(s => '<div class="settle"><span class="who">'+esc(s.from)+' → '+esc(s.to)+'</span><span class="amt">'+money(s.amount)+'</span></div>').join('');
    }
    el.innerHTML = html;
  }

  function render(){ renderPeople(); renderPayerOptions(); renderExpenses(); renderResults(); }

  function askConfirm(container, message, onYes){
    const el = $(container);
    el.innerHTML = '<span class="msg">'+esc(message)+'</span>'+
      '<button class="btn" type="button" data-act="cancel">Cancel</button>'+
      '<button class="btn btn-primary" type="button" data-act="yes">Yes</button>';
    el.hidden = false;
    el.querySelectorAll('button').forEach(b => b.addEventListener('click', () => {
      el.hidden = true; el.innerHTML = '';
      if(b.dataset.act === 'yes') onYes();
    }));
    el.querySelector('[data-act="yes"]').focus();
  }

  // Events
  $('addPerson').addEventListener('click', () => {
    const inp = $('personName');
    if(!addPerson(inp.value)){ status('Add a name that isn\'t already on the list.'); return; }
    inp.value = ''; status('');
  });
  $('personName').addEventListener('keydown', e => { if(e.key === 'Enter'){ e.preventDefault(); $('addPerson').click(); } });

  $('peopleList').addEventListener('click', e => {
    const btn = e.target.closest('[data-del-person]'); if(!btn) return;
    const id = btn.dataset.delPerson; const p = personById(id);
    askConfirm('personConfirm', 'Remove '+p.name+'? Their expenses will be dropped.', () => removePerson(id));
  });

  $('expForm').addEventListener('submit', e => {
    e.preventDefault();
    const err = $('expError'); err.textContent = '';
    const title = $('expTitle').value.trim();
    const amount = parseFloat($('expAmount').value);
    const payerId = $('expPayer').value;
    if(!title){ err.textContent = 'Please describe the expense.'; return; }
    if(!(amount > 0)){ err.textContent = 'Enter an amount greater than zero.'; return; }
    if(!payerId){ err.textContent = 'Add at least one person first.'; return; }
    const splitVal = $('expSplit').value;
    const splitIds = splitVal === 'all' ? state.people.map(p => p.id) : [splitVal];
    state.expenses.push({ id:'e'+(state.nextExpense++), title, amount, payerId, splitIds });
    save(); render(); status('Added: '+title);
    $('expTitle').value = ''; $('expAmount').value = '';
  });

  $('expList').addEventListener('click', e => {
    const btn = e.target.closest('[data-del-expense]'); if(!btn) return;
    const id = btn.dataset.delExpense; const ex = state.expenses.find(x => x.id === id);
    askConfirm('expConfirm', 'Delete "'+ex.title+'"?', () => removeExpense(id));
  });

  load().then(render);
})();
</script>
</body>
</html>
